here = fileparts(fileparts(mfilename('fullpath'))); addpath(here); addpath([here '/em']);
R('pZ isIntersecting approx', 'out=num2str(isIntersecting(polyZonotope([0;0],eye(2),[],[1 1;1 1]),interval([0;0],[1;1]),''approx''));');
R('polygon randPoint', 'r=randPoint(polygon([0 1 1 0],[0 0 1 1]),''all'',''extreme''); out=mat2str(r);');
R('polygon removeCollinear', 'P=polygon([0 3 3 2 2 1 1 0],[0 0 3 3 1 1 3 3]); Q=removeCollinearPoints(P); out=sprintf(''area before %g after %g  contains(1.5,2) before %d after %d'',area(P.set),area(Q.set),contains(P,[1.5;2]),contains(Q,[1.5;2]));');
R('polygon repr origin', 'out=num2str(representsa(polygon.empty(),''origin''));');
R('polytope cartProd', 'P1=polytope([1;-1],[1;0]); P2=polytope(-1,0); isBounded(P1); P=cartProd(P1,P2); out=num2str(isBounded(P));');
R('polytope compact', 'P=polytope([],[],[2;2],[1;1]); Q=compact(P); out=sprintf(''Ae=%s be=%s'',mat2str(Q.Ae),mat2str(Q.be));');
R('polytope convHull', 'P=polytope([1;-1],[0;-1]); S=polytope([1;-1],[1;0]); r=convHull(P,S); out=sprintf(''P empty %d; hull empty %d'',representsa(P,''emptySet''),representsa(r,''emptySet''));');
R('polytope isFullDim', 'P=polytope([eye(2);-eye(2);0 0],[1;1;1;1;0]); out=num2str(isFullDim(P));');
R('polytope isIntersecting', 'P1=polytope([eye(2);-eye(2)],ones(4,1)); P2=polytope([5 5;6 5;5 6]''); out=num2str(isIntersecting(P1,P2));');
R('polytope isequal', 'P1=polytope([1;1;-1],[1;1;0]); P2=polytope(-1,0); out=num2str(isequal(P1,P2));');
R('polytope minkDiff', 'r=minkDiff(polytope([1;-1],[1;1]),polytope(1,0)); out=sprintf(''empty=%d contains0=%d'',representsa(r,''emptySet''),contains(r,0));');
R('polytope mldivide', 'r=mldivide(polytope([1;-1],[2;0]),polytope([1;-1],[3;-1])); out=sprintf(''empty=%d contains0=%d'',representsa(r,''emptySet''),contains(r,0));');
R('polytope plus', 'r=polytope.Inf(2)+polytope.empty(2); out=sprintf(''empty=%d fullspace=%d'',representsa(r,''emptySet''),representsa(r,''fullspace''));');
R('polytope representsa interval', 'P=polytope([eye(2);-eye(2);1 1],[2;2;0;0;0]); out=num2str(representsa(P,''interval''));');
R('probZ interval', 'pz=probZonotope([0 1],zeros(1,1)); I=interval(pz); out=sprintf(''[%g,%g] sup=%g'',I.inf,I.sup,sup(pz));');
R('probZ mtimes', 'pz=probZonotope([0;0],eye(2)); R=interval(2*eye(2))*pz; out=sprintf(''cov %s g %s ; sigma(pz)=%s'',mat2str(R.cov),mat2str(R.g),mat2str(sigma(R)));');
R('probZ reduce', 'out=class(reduce(probZonotope([0 1;0 1],eye(2)),''althoff'',1));');
R('SpS contains', 'S=spectraShadow([1 0],[0;0],[1;1]); out=sprintf(''contains(1,0)=%d  contains(1,1)=%d'',contains(S,[1;0]),contains(S,[1;1]));');
R('SpS isBounded', 'S=spectraShadow([1 0],0,0); out=num2str(isBounded(S));');
R('SpS isFullDim', 'S=spectraShadow([1 0],0,1e-9); out=num2str(isFullDim(S));');
R('SpS mtimes', 'S=spectraShadow.Inf(1); R=[1;0]*S; out=sprintf(''isFullDim(M*SpS)=%d'',isFullDim(R));');
R('SpS repr fullspace', 'S=spectraShadow([1 0],[0;0],[1;1]); out=num2str(representsa(S,''fullspace''));');
R('SpS supportFunc', 'S=spectraShadow([1 0],0,0); out=sprintf(''%g'',supportFunc(S,1,''upper''));');
R('taylm asin', 'r=asin(taylm(interval(-1,1),7)); I=interval(r); out=sprintf(''interval(asin(taylm)) = [%g,%g]; pi/2=%g'',I.inf,I.sup,pi/2);');
R('zonoBundle isequal', 'a=zonoBundle({zonotope(0,1)}); b=zonoBundle({zonotope(0,1),zonotope(2,0)}); out=num2str(isequal(a,b));');
R('zonoBundle lift', 'r=lift(zonoBundle({zonotope([1;2;3])}),3,[2 3 1]); I=interval(r); out=mat2str(I.inf);');
